// Clean the question (remove the @mention and bold stars)
const question = $('Slack Trigger').first().json.text
  .replace(/<@[^>]+>/g, '').replace(/\*/g, '').trim();

// Turn the 54 rows into one simple list (one line per candidate)
const rows = $input.all().map(i => i.json);
const list = rows.map(r =>
  `${r.email} | ${r.name} | ${r.role} | ${r.location} | languages: ${r.languages} | skills: ${r.skills} | total years: ${r.years_total} | US hours: ${r.us_hours} | CV file: ${r.cv_file}`
).join('\n');

return [{ json: { question, list, count: rows.length } }];

