parameters.jsCode:
const out = $input.first().json.output || {};
const rows = $('Get all candidates').all().map(i => i.json);
const byEmail = {};
rows.forEach(r => byEmail[String(r.email).trim().toLowerCase()] = r);
const q = $('Build candidate list').first().json.question;

// SAFETY: keep only people who really exist in the database
const real = (out.candidates || [])
  .filter(c => byEmail[String(c.email).trim().toLowerCase()])
  .slice(0, 5);

let message;
if (real.length === 0) {
  message = `❌ *No good match* for: _${q}_\n${out.message || 'Nobody in the database meets all the requirements.'}`;
} else {
  message = `🔎 *Top ${real.length} for:* _${q}_\n\n` + real.map((c, i) => {
    const r = byEmail[String(c.email).trim().toLowerCase()];
    return `*${i + 1}. ${r.name}*  –  score *${c.score}/100*\n${c.reason}\n📄 CV: ${r.cv_file}`;
  }).join('\n\n');
}
return [{ json: { message, candidates: real } }];
